class Solution:
    def minInteger(self, num: str, k: int) -> str:
        rem = list(num)
        res = []
        while rem and k > 0:
            best = None
            for d in range(10):
                ch = str(d)
                try:
                    j = rem.index(ch)
                except ValueError:
                    continue
                if j <= k:
                    best = (j, ch)
                    break
            if best is None:
                break
            j, ch = best
            k -= j
            rem.pop(j)
            res.append(ch)
        return ''.join(res) + ''.join(rem)

