class Solution {
public:
    string minInteger(string num, int k) {
        string res;
        while (!num.empty() && k > 0) {
            bool moved = false;
            for (char d = '0'; d <= '9' && !moved; d++) {
                size_t j = num.find(d);
                if (j != string::npos && (int)j <= k) {
                    k -= (int)j;
                    num.erase(j, 1);
                    res.push_back(d);
                    moved = true;
                }
            }
            if (!moved) break;
        }
        return res + num;
    }
};

