        StringBuilder rem = new StringBuilder(num);
        StringBuilder res = new StringBuilder();
        while (rem.length() > 0 && k > 0) {
            boolean moved = false;
            for (char d = '0'; d <= '9' && !moved; d++) {
                int j = rem.indexOf(String.valueOf(d));
                if (j >= 0 && j <= k) {
                    k -= j;
                    rem.deleteCharAt(j);
                    res.append(d);
                    moved = true;
                }
            }
            if (!moved) break;
        }
        return res.append(rem).toString();
    }
}

