class Solution:
    def minInteger(self, num: str, k: int) -> str:
        n = len(num)
        pos = [[] for _ in range(10)]
        for i in range(n - 1, -1, -1):
            pos[int(num[i])].append(i)
        tree = [0] * (n + 1)

        def add(i):
            i += 1
            while i <= n:
                tree[i] += 1
                i += i & (-i)

        def query(i):
            i += 1
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & (-i)
            return s

        res = []
        for _ in range(n):
            for d in range(10):
                if pos[d]:
                    p = pos[d][-1]
                    if p - query(p) <= k:
                        k -= p - query(p)
                        pos[d].pop()
                        add(p)
                        res.append(chr(48 + d))
                        break
        return ''.join(res)

