class Solution {
public:
    string minInteger(string num, int k) {
        int n = num.size();
        vector<vector<int>> pos(10);
        for (int i = n - 1; i >= 0; i--) pos[num[i] - '0'].push_back(i);
        vector<int> tree(n + 1, 0);
        auto add = [&](int i) { for (i++; i <= n; i += i & (-i)) tree[i]++; };
        auto query = [&](int i) { int s = 0; for (i++; i > 0; i -= i & (-i)) s += tree[i]; return s; };
        string res;
        for (int step = 0; step < n; step++) {
            for (int d = 0; d < 10; d++) {
                if (!pos[d].empty()) {
                    int p = pos[d].back();
                    int cost = p - query(p);
                    if (cost <= k) {
                        k -= cost;
                        pos[d].pop_back();
                        add(p);
                        res.push_back('0' + d);
                        break;
                    }
                }
            }
        }
        return res;
    }
};

