        List<List<Integer>> pos = new ArrayList<>();
        for (int d = 0; d < 10; d++) pos.add(new ArrayList<>());
        for (int i = n - 1; i >= 0; i--) pos.get(num.charAt(i) - '0').add(i);
        int[] tree = new int[n + 1];
        for (int step = 0; step < n; step++) {
            for (int d = 0; d < 10; d++) {
                List<Integer> st = pos.get(d);
                if (!st.isEmpty()) {
                    int p = st.get(st.size() - 1);
                    int cost = p - query(tree, p);
                    if (cost <= k) {
                        k -= cost;
                        st.remove(st.size() - 1);
                        add(tree, p, n);
